mapper.update:
MERGE INTO edudoc_chunk_embedding tgt USING (
SELECT HEXTORAW(#{v.chunkIdHex}) AS chunk_id, HEXTORAW(#{modelProfileIdHex}) AS model_profile_id, #{v.embeddingText} AS embedding_text, SYS_GUID() AS new_id FROM DUAL
) src ON (tgt.chunk_id = src.chunk_id AND tgt.model_profile_id = src.model_profile_id) WHEN MATCHED THEN UPDATE SET tgt.embedding = TO_VECTOR(src.embedding_text, ${dimension}, FLOAT32), tgt.embedding_status = 'READY' WHEN NOT MATCHED THEN INSERT (id, chunk_id, model_profile_id, embedding, embedding_status) VALUES (src.new_id, src.chunk_id, src.model_profile_id, TO_VECTOR(src.embedding_text, ${dimension}, FLOAT32), 'READY')
